import{OCEAN_CONFIG as l}from"./config.min.js";function i(n,t,r){if(t<=n)return r>=t?1:0;const e=Math.max(0,Math.min(1,(r-n)/(t-n)));return e*e*(3-2*e)}function m(n,t,r){return n+(t-n)*r}export function arcProgress(n,t=l.storm){const r=t.seconds>0?t.seconds:1;return Math.max(0,Math.min(1,n/r))}export function stageAt(n,t=l.storm){const r=t.stages;let e=r[0];for(let a=0;a<r.length;a++)n>=r[a].from&&(e=r[a]);return e}export function stageProgress(n,t=l.storm){const r=t.stages;for(let e=0;e<r.length;e++){const a=r[e].from,o=e+1<r.length?r[e+1].from:t.seconds;if(n>=a&&(n<o||e===r.length-1))return o<=a?1:Math.max(0,Math.min(1,(n-a)/(o-a)))}return 0}export function swellAt(n,t=l.storm){return curveAt(n,t.swell,t)}export function leanAt(n,t=l.storm){return curveAt(n,t.lean,t)}export function gloomAt(n,t=l.storm){return curveAt(n,t.gloom,t)}export function surgeAt(n,t=l.storm){return curveAt(n,t.surge,t)}export function curveAt(n,t,r=l.storm){if(!t||t.length===0)return 0;if(t.length===1)return t[0].value;const e=Math.max(0,Math.min(r.seconds,n));if(e<=t[0].at)return t[0].value;const a=t[t.length-1];if(e>=a.at)return a.value;for(let o=1;o<t.length;o++)if(e<=t[o].at){const s=t[o-1],u=t[o];return m(s.value,u.value,i(s.at,u.at,e))}return a.value}export function engulfAt(n,t=l){const r=t.camera.height,e=t.storm.engulfWashMetres;return i(r,r+e,n)}export function washEnvelope(n,t,r,e=l.storm){const a=n&&typeof n=="object"?n:{wash:0,target:0,attacking:!1},o=Math.max(0,r),s=e.washReleaseSeconds>0?e.washReleaseSeconds:1,u=e.washAttackSeconds>0?e.washAttackSeconds:.2,h=t-a.target;let c=a.attacking;o>0&&h/o>1/s&&(c=!0);let f;return c?(f=Math.min(t,a.wash+o/u),f>=t-1e-9&&(c=!1)):f=Math.max(0,a.wash-o/s),{wash:f,target:t,attacking:c}}export function frontAt(n,t=l.storm){const r=t.tsunami;if(!r||n<r.startAt)return null;const e=r.arriveAt-r.startAt,a=e>0?Math.min(1,(n-r.startAt)/e):1,o=r.riseFar+(r.riseNear-r.riseFar)*a,s=Math.pow(a,.7);return{z:r.fromZ+(r.toZ-r.fromZ)*s,rise:o*i(0,.1,a),width:r.frontWidthFar+(r.frontWidthNear-r.frontWidthFar)*a,foam:r.frontFoam*i(0,.15,a),swellBehind:r.swellBehind}}export function clarityAt(n,t=l.storm){return curveAt(n,t.clarity,t)}export function lullFrontAt(n,t=l.storm){const r=t.lull;if(!r||n<r.startAt)return null;const e=r.endAt-r.startAt,a=e>0?Math.min(1,(n-r.startAt)/e):1;return a>=1?null:{z:r.fromZ+(r.toZ-r.fromZ)*a,width:r.width,before:swellAt(r.startAt,t)}}export function frontLevelAt(n,t){return t?t.rise*(1-i(t.z-t.width,t.z+t.width,n)):0}export function surfaceAtCamera(n,t=l){const{beach:r,camera:e}=t,a=(e.z-r.shoreZ)*r.slope;return Math.max(a,n)}export function fadeAt(n,t=l.storm){const r=t.seconds-t.fadeSeconds;return i(r,t.seconds,n)}export function stormStateAt(n,t=l,r=null){const e=t.storm,a=surgeAt(n,e),o=frontAt(n,e),s=a+frontLevelAt(t.camera.z,o),u=r??surfaceAtCamera(s,t);return{seconds:n,progress:arcProgress(n,e),stage:stageAt(n,e).name,swell:swellAt(n,e),lean:leanAt(n,e),gloom:gloomAt(n,e),clarity:clarityAt(n,e),surge:a,front:o,lull:lullFrontAt(n,e),engulf:engulfAt(u,t),fade:fadeAt(n,e),finished:n>=e.seconds}}
